#include <stdio.h>
#include <stdbool.h>  /* C99: provides bool, true, false */

int main(void) {
    char c = 'A';           /* 1 byte. Range: -128 to 127 (signed) */
    unsigned char uc = 255; /* 1 byte. Range: 0 to 255 */
    int i = 42;             /* Typically 4 bytes */
    short s = 32000;        /* Typically 2 bytes */
    long l = 123456789L;    /* L suffix for long literal */
    long long ll = 9LL;     /* LL suffix for long long */
    float f = 3.14f;        /* f suffix for float */
    double d = 2.71828;     /* Default for decimal literals */
    bool flag = true;       /* C99: _Bool with stdbool.h */

    printf("sizeof(char) = %zu\n", sizeof(c));
    printf("sizeof(int) = %zu\n", sizeof(i));
    printf("sizeof(long) = %zu\n", sizeof(l));
    printf("sizeof(float) = %zu\n", sizeof(f));
    printf("sizeof(double) = %zu\n", sizeof(d));
    printf("sizeof(bool) = %zu\n", sizeof(flag));

    return 0;
}

/* Type modifiers and ranges */
#include <stdio.h>
#include <limits.h>  /* Provides INT_MAX, CHAR_MIN, etc. */

int main(void) {
    /* signed vs unsigned behavior */
    unsigned int u = 0;
    u = u - 1;  /* Wraps around! No crash, but logic error. */
    printf("0 - 1 as unsigned = %u\n", u);  /* Prints UINT_MAX */

    /* Overflow in signed is UNDEFINED BEHAVIOR in C */
    int max = INT_MAX;
    /* max = max + 1;  // DON'T DO THIS. Could crash, wrap, or worse. */

    printf("INT_MAX = %d\n", INT_MAX);
    printf("UINT_MAX = %u\n", UINT_MAX);

    return 0;
}

#include <stdio.h>

int main(void) {
    /* Arithmetic */
    int a = 17, b = 5;
    printf("17 / 5 = %d\n", a / b);   /* 3 (integer division truncates) */
    printf("17 %% 5 = %d\n", a % b);   /* 2 (remainder) */

    /* Short-circuit evaluation */
    int x = 0, y = 10;
    if (x != 0 && y / x > 5) {  /* y/x is NEVER executed because x!=0 is false */
        printf("This won't print\n");
    }

    /* Bitwise operations */
    unsigned int flags = 0b1010;  /* Binary literal (C23); use 0x0A for older standards */
    flags |= 0b0100;              /* Set bit 2 */
    flags &= ~0b0010;             /* Clear bit 1 */
    flags ^= 0b1000;              /* Toggle bit 3 */
    printf("flags = %u\n", flags);

    /* Ternary operator */
    int max = (a > b) ? a : b;
    printf("max = %d\n", max);

    /* Precedence trap */
    int result = a & b + 3;  /* + has higher precedence than & */
    /* Equivalent to: a & (b + 3), NOT (a & b) + 3 */
    printf("a & b + 3 = %d\n", result);

    return 0;
}

/* Implicit vs Explicit Type Conversion (Casting) */
#include <stdio.h>

int main(void) {
    int i = 5;
    double d = i / 2;       /* Integer division! d = 2.0, not 2.5 */
    double e = i / 2.0;     /* i promoted to double. e = 2.5 */
    double f = (double)i / 2;  /* Explicit cast. f = 2.5 */

    printf("d = %f, e = %f, f = %f\n", d, e, f);

    /* Integer promotion: char/short promoted to int in expressions */
    char c = 100;
    char c2 = 100;
    /* c + c2 is computed as int, then truncated if assigned back to char */
    char sum = c + c2;  /* 200 fits in char. But 150+150 would overflow. */
    printf("sum = %d\n", sum);

    return 0;
}

#include <stdio.h>

int main(void) {
    /* if-else ladder */
    int score = 85;
    if (score >= 90) {
        printf("Grade: A\n");
    } else if (score >= 80) {
        printf("Grade: B\n");
    } else if (score >= 70) {
        printf("Grade: C\n");
    } else {
        printf("Grade: F\n");
    }

    /* switch with fall-through (intentional) */
    int month = 3;
    switch (month) {
        case 12: case 1: case 2:
            printf("Winter\n"); break;
        case 3: case 4: case 5:
            printf("Spring\n"); break;
        case 6: case 7: case 8:
            printf("Summer\n"); break;
        case 9: case 10: case 11:
            printf("Autumn\n"); break;
        default:
            printf("Invalid month\n");
    }

    /* for loop: compute factorial */
    int n = 5, fact = 1;
    for (int i = 1; i <= n; i++) {  /* C99: declaration in for loop */
        fact *= i;
    }
    printf("%d! = %d\n", n, fact);

    /* while with break */
    int guess = 0;
    while (1) {  /* infinite loop */
        guess++;
        if (guess == 7) {
            printf("Found it: %d\n", guess);
            break;
        }
    }

    return 0;
}

/* DANGEROUS: goto for error cleanup (acceptable pattern) */
#include <stdio.h>
#include <stdlib.h>

int process_file(const char* path) {
    FILE* fp = fopen(path, "r");
    if (!fp) goto cleanup_file;

    char* buffer = malloc(1024);
    if (!buffer) goto cleanup_buffer;

    /* ... do processing ... */
    printf("Processing complete.\n");

    free(buffer);
cleanup_buffer:
    fclose(fp);
cleanup_file:
    return (fp != NULL) ? 0 : -1;
}

/* BETTER: structured approach without goto */
int process_file_better(const char* path) {
    FILE* fp = fopen(path, "r");
    if (!fp) return -1;

    char* buffer = malloc(1024);
    if (!buffer) {
        fclose(fp);
        return -1;
    }

    /* ... do processing ... */
    printf("Processing complete.\n");

    free(buffer);
    fclose(fp);
    return 0;
}

