static int counter(void);  /* static function: visible only in this file */

int main(void) {
    int x = 5, y = 10;

    /* Call by value */
    printf("add(5, 10) = %d\n", add(x, y));

    /* This will NOT swap x and y */
    swap_wrong(x, y);
    printf("After swap_wrong: x=%d, y=%d\n", x, y);

    /* static variable demo */
    printf("counter: %d\n", counter());
    printf("counter: %d\n", counter());
    printf("counter: %d\n", counter());

    /* Recursion: factorial */
    printf("5! = %d\n", factorial(5));

    return 0;
}

/* Function definition */
int add(int a, int b) {
    return a + b;
}

void swap_wrong(int a, int b) {
    int temp = a;
    a = b;
    b = temp;
    /* These are local copies. Original x and y are unchanged. */
}

int counter(void) {
    static int count = 0;  /* Retains value between calls */
    count++;
    return count;
}

int factorial(int n) {
    if (n <= 1) return 1;
    return n * factorial(n - 1);
}

