/* Array decay: the function receives a pointer, not the array */
void print_array(int arr[], int len) {
    /* sizeof(arr) here would give POINTER size, not array size! */
    for (int i = 0; i < len; i++) {
        printf("%d ", arr[i]);
    }
    printf("\n");
}

