#include <stdio.h>

int main(void) {
    int x = 42;
    int* ptr = &x;  /* ptr stores the address of x */

    printf("x = %d\n", x);
    printf("Address of x: %p\n", (void*)&x);
    printf("ptr = %p\n", (void*)ptr);
    printf("*ptr = %d\n", *ptr);  /* Dereference: read value at address */

    *ptr = 100;  /* Dereference: write value at address */
    printf("x is now %d\n", x);

    /* Pointer arithmetic */
    int arr[] = {10, 20, 30, 40, 50};
    int* p = arr;  /* Points to arr[0] */

    printf("*p = %d\n", *p);        /* 10 */
    printf("*(p+1) = %d\n", *(p+1)); /* 20 */
    printf("p[2] = %d\n", p[2]);     /* 30 (same as *(p+2)) */

    /* Pointer subtraction gives element count */
    int* end = &arr[4];
    printf("Elements between p and end: %td\n", end - p);

    /* Void pointer */
    void* vp = &x;
    printf("Value via void*: %d\n", *(int*)vp);

    /* NULL pointer */
    int* np = NULL;
    if (np == NULL) {
        printf("np is NULL, safe to check before use.\n");
    }

    return 0;
}

/* Pointers enable true pass-by-reference */
#include <stdio.h>

void swap(int* a, int* b) {
    int temp = *a;
    *a = *b;
    *b = temp;
    /* We dereference and modify the values at the caller's addresses */
}

int main(void) {
    int x = 5, y = 10;
    printf("Before: x=%d, y=%d\n", x, y);
    swap(&x, &y);  /* Pass addresses, not values */
    printf("After:  x=%d, y=%d\n", x, y);

    /* Multiple return values via pointers */
    int min, max;
    get_min_max(3, 7, &min, &max);
    printf("min=%d, max=%d\n", min, max);

    return 0;
}

void get_min_max(int a, int b, int* min_out, int* max_out) {
    *min_out = (a < b) ? a : b;
    *max_out = (a > b) ? a : b;
}

#include <stdio.h>
#include <string.h>

int main(void) {
    /* String literal: stored in read-only memory */
    char* str1 = "Hello";  /* Pointer to read-only memory. DO NOT modify. */
    char str2[] = "World"; /* Array copy on stack. Modification is OK. */

    printf("str1: %s (length: %zu)\n", str1, strlen(str1));
    printf("str2: %s (length: %zu)\n", str2, strlen(str2));

    /* String copying — DANGEROUS if dest is too small */
    char dest[20];
    strcpy(dest, str1);  /* Copies including null terminator */
    strcat(dest, " ");  /* Appends space */
    strcat(dest, str2);  /* Appends str2 */
    printf("dest: %s\n", dest);

    /* Safe comparison */
    if (strcmp(str1, "Hello") == 0) {
        printf("str1 equals 'Hello'\n");
    }

    /* Finding substrings */
    char* found = strstr(dest, "orl");
    if (found) {
        printf("Found 'orl' at position: %td\n", found - dest);
    }

    /* Character search */
    char* first_l = strchr(dest, 'l');
    printf("First 'l' at position: %td\n", first_l - dest);

    return 0;
}

/* SAFE string handling */
#include <stdio.h>
#include <string.h>

int main(void) {
    char src[] = "This is a very long string that could overflow a small buffer";
    char dest[20];

    /* DANGEROUS: strcpy(dest, src);  // Buffer overflow! */

    /* Safer: strncpy (but watch the null terminator!) */
    strncpy(dest, src, sizeof(dest) - 1);
    dest[sizeof(dest) - 1] = '\0';  /* FORCE null termination */
    printf("Truncated safely: %s\n", dest);

    /* Even safer: track lengths explicitly */
    size_t src_len = strlen(src);
    size_t dest_size = sizeof(dest);
    if (src_len >= dest_size) {
        printf("Warning: string truncated. Need %zu bytes, have %zu.\n",
               src_len + 1, dest_size);
    }

    /* C11: safer functions (optional support) */
    /* strcpy_s(dest, sizeof(dest), src);  // Runtime check, aborts on overflow */

    return 0;
}

