};

int main(void) {
    struct Point p1 = {10, 20};
    struct Point* ptr = &p1;

    printf("Point: (%d, %d)\n", p1.x, p1.y);
    printf("Via pointer: (%d, %d)\n", ptr->x, ptr->y);

    struct Student s = {"Alice", 21, 3.85};
    printf("Student: %s, age %d, GPA %.2f\n", s.name, s.age, s.gpa);

    /* Union: same memory, different views */
    union Data d;
