    printf("As char[0]: %c\n", d.str[0]);  /* 65 = 'A' */

    printf("sizeof(struct Point) = %zu\n", sizeof(struct Point));
    printf("sizeof(union Data) = %zu\n", sizeof(union Data));
    printf("sizeof(struct Flags) = %zu\n", sizeof(struct Flags));

    /* Bit-field usage */
    struct Flags f = {1, 5, 10};
    printf("active=%u, priority=%u, category=%u\n",
           f.is_active, f.priority, f.category);

