#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(void) {
    /* malloc: allocate uninitialized memory */
    int* arr = malloc(5 * sizeof(int));
    if (arr == NULL) {
        fprintf(stderr, "malloc failed\n");
        return 1;
    }
    for (int i = 0; i < 5; i++) {
        arr[i] = (i + 1) * 10;
    }

    /* calloc: allocate and zero-initialize */
    int* zeros = calloc(5, sizeof(int));
    if (zeros == NULL) {
        free(arr);
        return 1;
    }
    printf("calloc result: %d %d %d\n", zeros[0], zeros[2], zeros[4]);

    /* realloc: grow the array */
    int* bigger = realloc(arr, 10 * sizeof(int));
    if (bigger == NULL) {
        free(arr);
        free(zeros);
        return 1;
    }
    arr = bigger;  /* Update pointer (may have moved) */
    for (int i = 5; i < 10; i++) {
        arr[i] = (i + 1) * 10;
    }
    printf("Reallocated array: ");
    for (int i = 0; i < 10; i++) printf("%d ", arr[i]);
    printf("\n");

    /* strdup: allocates heap copy of string */
    char* copy = strdup("Hello, Heap!");
    printf("%s\n", copy);

    /* CRITICAL: free everything exactly once */
    free(arr);      /* Matches malloc/realloc */
    free(zeros);    /* Matches calloc */
    free(copy);     /* Matches strdup */
    /* arr = NULL; zeros = NULL; copy = NULL;  // Good practice after free */

    return 0;
}

