int main(void) {
    /* Writing text to a file */
    FILE* fp = fopen("data.txt", "w");
    if (!fp) {
        perror("Failed to open data.txt");
        return 1;
    }

    fprintf(fp, "Name: %s\n", "Alice");
    fprintf(fp, "Score: %d\n", 95);
    fprintf(fp, "GPA: %.2f\n", 3.85);
    fclose(fp);

    /* Reading text from a file */
    fp = fopen("data.txt", "r");
    if (!fp) {
        perror("Failed to open data.txt");
        return 1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp) != NULL) {
        printf("Read: %s", line);  /* fgets keeps the newline */
    }
    fclose(fp);

    /* Binary I/O: write array of integers */
    int numbers[] = {10, 20, 30, 40, 50};
    fp = fopen("numbers.bin", "wb");
    if (!fp) {
        perror("Failed to open numbers.bin");
        return 1;
    }
    size_t written = fwrite(numbers, sizeof(int), 5, fp);
    printf("Wrote %zu integers\n", written);
    fclose(fp);

    /* Binary I/O: read back */
    int readback[5];
    fp = fopen("numbers.bin", "rb");
    if (!fp) {
        perror("Failed to open numbers.bin");
        return 1;
    }
    size_t read = fread(readback, sizeof(int), 5, fp);
    printf("Read %zu integers: ", read);
    for (size_t i = 0; i < read; i++) printf("%d ", readback[i]);
    printf("\n");
    fclose(fp);

    return 0;
}

/* Safe file copy with error handling */
#include <stdio.h>
#include <stdlib.h>

#define BUFFER_SIZE 4096

int copy_file(const char* src_path, const char* dst_path) {
    FILE* src = fopen(src_path, "rb");
    if (!src) {
        perror("Source file");
        return -1;
    }

    FILE* dst = fopen(dst_path, "wb");
    if (!dst) {
        perror("Destination file");
        fclose(src);
        return -1;
    }

    char buffer[BUFFER_SIZE];
    size_t bytes;
    while ((bytes = fread(buffer, 1, sizeof(buffer), src)) > 0) {
        if (fwrite(buffer, 1, bytes, dst) != bytes) {
            perror("Write error");
            fclose(src);
            fclose(dst);
            return -1;
        }
    }

    if (ferror(src)) {
        perror("Read error");
        fclose(src);
        fclose(dst);
        return -1;
    }

    fclose(src);
    fclose(dst);
    return 0;
}

int main(void) {
    if (copy_file("data.txt", "data_copy.txt") == 0) {
        printf("File copied successfully.\n");
    }
    return 0;
}

#include <stdio.h>
