/* Function pointer type for comparison */
typedef int (*CompareFunc)(const void*, const void*);

int compare_ints(const void* a, const void* b) {
    int ia = *(const int*)a;
    int ib = *(const int*)b;
    return (ia > ib) - (ia < ib);  /* Returns -1, 0, or 1 */
}

int compare_desc(const void* a, const void* b) {
    return -compare_ints(a, b);
}

/* Generic bubble sort using function pointers */
void bubble_sort(void* arr, size_t n, size_t size, CompareFunc cmp) {
    char* base = arr;
    char* temp = malloc(size);
    for (size_t i = 0; i < n - 1; i++) {
        for (size_t j = 0; j < n - i - 1; j++) {
            void* a = base + j * size;
            void* b = base + (j + 1) * size;
            if (cmp(a, b) > 0) {
                memcpy(temp, a, size);
                memcpy(a, b, size);
                memcpy(b, temp, size);
            }
        }
    }
    free(temp);
}

/* Pointer-to-pointer: allocate array inside function */
int create_matrix(int*** mat, int rows, int cols) {
    *mat = malloc(rows * sizeof(int*));
    if (!*mat) return -1;
    for (int i = 0; i < rows; i++) {
        (*mat)[i] = calloc(cols, sizeof(int));
        if (!(*mat)[i]) return -1;
    }
    return 0;
}

void free_matrix(int** mat, int rows) {
    for (int i = 0; i < rows; i++) free(mat[i]);
    free(mat);
}

