#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int data;
    struct Node* next;
} Node;

Node* create_node(int value) {
    Node* n = malloc(sizeof(Node));
    if (!n) return NULL;
    n->data = value;
    n->next = NULL;
    return n;
}

void prepend(Node** head, int value) {
    Node* n = create_node(value);
    n->next = *head;
    *head = n;
}

void append(Node** head, int value) {
    Node* n = create_node(value);
    if (!*head) {
        *head = n;
        return;
    }
    Node* curr = *head;
    while (curr->next) curr = curr->next;
    curr->next = n;
}

void delete_value(Node** head, int value) {
    Node* curr = *head;
    Node* prev = NULL;
    while (curr) {
        if (curr->data == value) {
            if (prev) prev->next = curr->next;
            else *head = curr->next;
            free(curr);
            return;
        }
        prev = curr;
        curr = curr->next;
    }
}

void print_list(const Node* head) {
    while (head) {
        printf("%d -> ", head->data);
        head = head->next;
    }
    printf("NULL\n");
}

void free_list(Node* head) {
    while (head) {
        Node* temp = head;
        head = head->next;
        free(temp);
    }
}

int main(void) {
    Node* list = NULL;

    append(&list, 10);
    append(&list, 20);
    append(&list, 30);
    prepend(&list, 5);
    print_list(list);

    delete_value(&list, 20);
    print_list(list);

    free_list(list);
    return 0;
}

/* Doubly linked list node */
#include <stdio.h>
#include <stdlib.h>

typedef struct DNode {
    int data;
    struct DNode* prev;
    struct DNode* next;
} DNode;

typedef struct {
    DNode* head;
    DNode* tail;
} DList;

void dlist_append(DList* list, int value) {
    DNode* n = malloc(sizeof(DNode));
    n->data = value;
    n->next = NULL;
    n->prev = list->tail;

    if (list->tail) list->tail->next = n;
    else list->head = n;
    list->tail = n;
}

void dlist_print_forward(const DList* list) {
    DNode* curr = list->head;
    while (curr) {
        printf("%d <-> ", curr->data);
        curr = curr->next;
    }
    printf("NULL\n");
}

void dlist_print_backward(const DList* list) {
    DNode* curr = list->tail;
    while (curr) {
        printf("%d <-> ", curr->data);
        curr = curr->prev;
    }
    printf("NULL\n");
}

void dlist_free(DList* list) {
    DNode* curr = list->head;
    while (curr) {
        DNode* temp = curr;
        curr = curr->next;
        free(temp);
    }
    list->head = list->tail = NULL;
}

int main(void) {
    DList list = {NULL, NULL};
    dlist_append(&list, 1);
    dlist_append(&list, 2);
    dlist_append(&list, 3);
    printf("Forward:  "); dlist_print_forward(&list);
    printf("Backward: "); dlist_print_backward(&list);
    dlist_free(&list);
    return 0;
}

