/* Error handling patterns: goto cleanup vs nested ifs */
#include <stdio.h>
#include <stdlib.h>

/* Pattern 1: Nested ifs (deeply indented, hard to read) */
int process_nested(const char* in_path, const char* out_path) {
    FILE* in = fopen(in_path, "r");
    if (in) {
        FILE* out = fopen(out_path, "w");
        if (out) {
            char* buffer = malloc(1024);
            if (buffer) {
                /* ... process ... */
                printf("Success with nested ifs\n");
                free(buffer);
            }
            fclose(out);
        }
        fclose(in);
    }
    return 0;
}

/* Pattern 2: goto cleanup (cleaner, single exit point) */
int process_goto(const char* in_path, const char* out_path) {
    FILE* in = NULL;
    FILE* out = NULL;
    char* buffer = NULL;
    int status = -1;

    in = fopen(in_path, "r");
    if (!in) goto cleanup;

    out = fopen(out_path, "w");
    if (!out) goto cleanup;

    buffer = malloc(1024);
    if (!buffer) goto cleanup;

    /* ... process ... */
    printf("Success with goto cleanup\n");
    status = 0;

cleanup:
    free(buffer);
    if (out) fclose(out);
    if (in) fclose(in);
    return status;
}

int main(void) {
    process_nested("in.txt", "out.txt");
    process_goto("in.txt", "out.txt");
    return 0;
}

