#include <stdio.h>

/* Factorial: n! = n * (n-1)!, base case 0! = 1 */
unsigned long long factorial(int n) {
    if (n < 0) return 0;
    if (n == 0 || n == 1) return 1;
    return n * factorial(n - 1);
}

/* Tail-recursive factorial */
unsigned long long fact_tail(int n, unsigned long long acc) {
    if (n <= 1) return acc;
    return fact_tail(n - 1, n * acc);
}

/* Binary search: recursive divide and conquer */
int binary_search(int arr[], int left, int right, int target) {
    if (left > right) return -1;
    int mid = left + (right - left) / 2;
    if (arr[mid] == target) return mid;
    if (arr[mid] > target)
        return binary_search(arr, left, mid - 1, target);
    return binary_search(arr, mid + 1, right, target);
}

/* Tower of Hanoi */
void hanoi(int n, char from, char to, char aux) {
    if (n == 0) return;
    hanoi(n - 1, from, aux, to);
    printf("Move disk %d from %c to %c\n", n, from, to);
    hanoi(n - 1, aux, to, from);
}

int main(void) {
    printf("5! = %llu\n", factorial(5));
    printf("5! (tail) = %llu\n", fact_tail(5, 1));
    int sorted[] = {2,5,8,12,16,23,38,56,72,91};
    printf("Found 23 at index %d\n", binary_search(sorted,0,9,23));
    printf("\nTower of Hanoi (3 disks):\n");
    hanoi(3, 'A', 'C', 'B');
    return 0;
}

/* Memoized Fibonacci */
#include <stdio.h>
#include <string.h>

#define MAX_N 50

unsigned long long fib_memo(int n, unsigned long long cache[]) {
    if (n <= 1) return n;
    if (cache[n] != 0) return cache[n];
    cache[n] = fib_memo(n - 1, cache) + fib_memo(n - 2, cache);
    return cache[n];
}

/* Iterative Fibonacci: O(n) time, O(1) space */
unsigned long long fib_iter(int n) {
    if (n <= 1) return n;
    unsigned long long prev = 0, curr = 1;
    for (int i = 2; i <= n; i++) {
        unsigned long long next = prev + curr;
        prev = curr;
        curr = next;
    }
    return curr;
}

int main(void) {
    unsigned long long cache[MAX_N] = {0};
    printf("fib_memo(40) = %llu\n", fib_memo(40, cache));
    printf("fib_iter(40) = %llu\n", fib_iter(40));
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

#define STACK_SIZE 100

typedef struct { int data[STACK_SIZE]; int top; } Stack;
void stack_init(Stack* s) { s->top = -1; }
bool stack_push(Stack* s, int val) {
    if (s->top >= STACK_SIZE - 1) return false;
    s->data[++s->top] = val; return true;
}
bool stack_pop(Stack* s, int* out) {
    if (s->top < 0) return false;
    *out = s->data[s->top--]; return true;
}

#define QUEUE_SIZE 8
typedef struct { int data[QUEUE_SIZE]; int front; int rear; int count; } Queue;
void queue_init(Queue* q) { q->front = 0; q->rear = -1; q->count = 0; }
bool enqueue(Queue* q, int val) {
    if (q->count >= QUEUE_SIZE) return false;
    q->rear = (q->rear + 1) % QUEUE_SIZE;
    q->data[q->rear] = val; q->count++; return true;
}
bool dequeue(Queue* q, int* out) {
    if (q->count == 0) return false;
    *out = q->data[q->front];
    q->front = (q->front + 1) % QUEUE_SIZE;
    q->count--; return true;
}

int main(void) {
    Stack s; stack_init(&s);
    stack_push(&s, 10); stack_push(&s, 20); stack_push(&s, 30);
    int val;
    while (stack_pop(&s, &val)) printf("Popped: %d\n", val);

    Queue q; queue_init(&q);
    for (int i = 1; i <= 5; i++) enqueue(&q, i * 10);
    printf("\nDequeued: ");
    while (dequeue(&q, &val)) printf("%d ", val);
    printf("\n");

    enqueue(&q, 100); enqueue(&q, 200);
    dequeue(&q, &val);
    enqueue(&q, 300);
    printf("After wrap: ");
    while (dequeue(&q, &val)) printf("%d ", val);
    printf("\n");
    return 0;
}

/* Linked List Stack and Queue */
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

typedef struct Node { int data; struct Node* next; } Node;

typedef struct { Node* top; } LLStack;
void lls_init(LLStack* s) { s->top = NULL; }
void lls_push(LLStack* s, int val) {
    Node* n = malloc(sizeof(Node));
    n->data = val; n->next = s->top; s->top = n;
}
bool lls_pop(LLStack* s, int* out) {
    if (!s->top) return false;
    Node* temp = s->top;
    *out = temp->data; s->top = temp->next; free(temp);
    return true;
}

typedef struct { Node* head; Node* tail; } LLQueue;
void llq_init(LLQueue* q) { q->head = q->tail = NULL; }
void llq_enqueue(LLQueue* q, int val) {
    Node* n = malloc(sizeof(Node));
    n->data = val; n->next = NULL;
    if (q->tail) q->tail->next = n;
    else q->head = n;
    q->tail = n;
}
bool llq_dequeue(LLQueue* q, int* out) {
    if (!q->head) return false;
    Node* temp = q->head;
    *out = temp->data;
    q->head = temp->next;
    if (!q->head) q->tail = NULL;
    free(temp); return true;
}

int main(void) {
    LLStack s; lls_init(&s);
    lls_push(&s, 1); lls_push(&s, 2); lls_push(&s, 3);
    int v;
    printf("LL Stack: ");
    while (lls_pop(&s, &v)) printf("%d ", v);
    printf("\n");

    LLQueue q; llq_init(&q);
    llq_enqueue(&q, 10); llq_enqueue(&q, 20); llq_enqueue(&q, 30);
    printf("LL Queue: ");
    while (llq_dequeue(&q, &v)) printf("%d ", v);
    printf("\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

typedef struct TreeNode {
    int data;
    struct TreeNode* left;
    struct TreeNode* right;
} TreeNode;

TreeNode* create_node(int value) {
    TreeNode* n = malloc(sizeof(TreeNode));
    n->data = value;
    n->left = n->right = NULL;
    return n;
}

TreeNode* bst_insert(TreeNode* root, int value) {
    if (root == NULL) return create_node(value);
    if (value < root->data)
        root->left = bst_insert(root->left, value);
    else if (value > root->data)
        root->right = bst_insert(root->right, value);
    return root;
}

TreeNode* bst_search(TreeNode* root, int value) {
    if (root == NULL || root->data == value) return root;
    if (value < root->data) return bst_search(root->left, value);
    return bst_search(root->right, value);
}

void inorder(const TreeNode* root) {
    if (root) {
        inorder(root->left);
        printf("%d ", root->data);
        inorder(root->right);
    }
}

void preorder(const TreeNode* root) {
    if (root) {
        printf("%d ", root->data);
        preorder(root->left);
        preorder(root->right);
    }
}

void postorder(const TreeNode* root) {
    if (root) {
        postorder(root->left);
        postorder(root->right);
        printf("%d ", root->data);
    }
}

int tree_height(const TreeNode* root) {
    if (!root) return -1;
    int left_h = tree_height(root->left);
    int right_h = tree_height(root->right);
    return 1 + (left_h > right_h ? left_h : right_h);
}

void free_tree(TreeNode* root) {
    if (root) {
        free_tree(root->left);
        free_tree(root->right);
        free(root);
    }
}

int main(void) {
    TreeNode* root = NULL;
    int values[] = {50, 30, 70, 20, 40, 60, 80};
    for (size_t i = 0; i < 7; i++)
        root = bst_insert(root, values[i]);

    printf("Inorder:  "); inorder(root); printf("\n");
    printf("Preorder: "); preorder(root); printf("\n");
    printf("Postorder:"); postorder(root); printf("\n");
    printf("Height: %d\n", tree_height(root));
    printf("Search 40: %s\n", bst_search(root, 40) ? "Found" : "Not found");

    free_tree(root);
    return 0;
}

/* BST deletion: three cases */
#include <stdio.h>
#include <stdlib.h>

typedef struct TreeNode {
    int data; struct TreeNode* left; struct TreeNode* right;
} TreeNode;

TreeNode* find_min(TreeNode* root) {
    while (root->left) root = root->left;
    return root;
}

TreeNode* bst_delete(TreeNode* root, int value) {
    if (!root) return NULL;
    if (value < root->data)
        root->left = bst_delete(root->left, value);
    else if (value > root->data)
        root->right = bst_delete(root->right, value);
    else {
        if (!root->left) {
            TreeNode* temp = root->right;
            free(root); return temp;
        }
        if (!root->right) {
            TreeNode* temp = root->left;
            free(root); return temp;
        }
        TreeNode* succ = find_min(root->right);
        root->data = succ->data;
        root->right = bst_delete(root->right, succ->data);
    }
    return root;
}

void inorder(const TreeNode* root) {
    if (root) {
        inorder(root->left);
        printf("%d ", root->data);
        inorder(root->right);
    }
}

int main(void) {
    printf("BST deletion has three cases:\n");
    printf("1. Leaf node: simply remove it\n");
    printf("2. One child: replace node with its child\n");
    printf("3. Two children: replace with inorder successor, delete successor\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

void bubble_sort(int arr[], int n) {
    for (int i = 0; i < n - 1; i++) {
        for (int j = 0; j < n - i - 1; j++) {
            if (arr[j] > arr[j + 1]) {
                int tmp = arr[j];
                arr[j] = arr[j + 1];
                arr[j + 1] = tmp;
            }
        }
    }
}

void insertion_sort(int arr[], int n) {
    for (int i = 1; i < n; i++) {
        int key = arr[i];
        int j = i - 1;
        while (j >= 0 && arr[j] > key) {
            arr[j + 1] = arr[j];
            j--;
        }
        arr[j + 1] = key;
    }
}

void merge(int arr[], int left, int mid, int right) {
    int n1 = mid - left + 1;
    int n2 = right - mid;
    int L[n1], R[n2];
    memcpy(L, &arr[left], n1 * sizeof(int));
    memcpy(R, &arr[mid + 1], n2 * sizeof(int));
    int i = 0, j = 0, k = left;
    while (i < n1 && j < n2)
        arr[k++] = (L[i] <= R[j]) ? L[i++] : R[j++];
    while (i < n1) arr[k++] = L[i++];
    while (j < n2) arr[k++] = R[j++];
}

void merge_sort(int arr[], int left, int right) {
    if (left < right) {
        int mid = left + (right - left) / 2;
        merge_sort(arr, left, mid);
        merge_sort(arr, mid + 1, right);
        merge(arr, left, mid, right);
    }
}

int partition(int arr[], int low, int high) {
    int pivot = arr[high];
    int i = low - 1;
    for (int j = low; j < high; j++) {
        if (arr[j] <= pivot) {
            i++;
            int tmp = arr[i]; arr[i] = arr[j]; arr[j] = tmp;
        }
    }
    int tmp = arr[i + 1]; arr[i + 1] = arr[high]; arr[high] = tmp;
    return i + 1;
}

void quick_sort(int arr[], int low, int high) {
    if (low < high) {
        int pi = partition(arr, low, high);
        quick_sort(arr, low, pi - 1);
        quick_sort(arr, pi + 1, high);
    }
}

void print_array(const int arr[], int n) {
    for (int i = 0; i < n; i++) printf("%d ", arr[i]);
    printf("\n");
}

int main(void) {
    int a1[] = {64, 34, 25, 12, 22, 11, 90};
    int n = 7;
    bubble_sort(a1, n);
    printf("Bubble:    "); print_array(a1, n);

    int a2[] = {64, 34, 25, 12, 22, 11, 90};
    insertion_sort(a2, n);
    printf("Insertion: "); print_array(a2, n);

    int a3[] = {64, 34, 25, 12, 22, 11, 90};
    merge_sort(a3, 0, n - 1);
    printf("Merge:     "); print_array(a3, n);

    int a4[] = {64, 34, 25, 12, 22, 11, 90};
    quick_sort(a4, 0, n - 1);
    printf("Quick:     "); print_array(a4, n);
    return 0;
}

/* Using stdlib qsort and bsearch */
#include <stdio.h>
#include <stdlib.h>

int cmp_int(const void* a, const void* b) {
    int ia = *(const int*)a;
    int ib = *(const int*)b;
    return (ia > ib) - (ia < ib);
}

int main(void) {
    int arr[] = {42, 7, 19, 3, 88, 15, 67};
    int n = sizeof(arr) / sizeof(arr[0]);

    qsort(arr, n, sizeof(int), cmp_int);
    printf("After qsort: ");
    for (int i = 0; i < n; i++) printf("%d ", arr[i]);
    printf("\n");

    int key = 19;
    int* found = bsearch(&key, arr, n, sizeof(int), cmp_int);
    if (found)
        printf("bsearch found %d at index %td\n", *found, found - arr);
    else
        printf("%d not found\n", key);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

#define TABLE_SIZE 16

typedef struct Entry {
    char* key;
    int value;
    struct Entry* next;
} Entry;

typedef struct {
    Entry* buckets[TABLE_SIZE];
    int count;
} HashTable;

unsigned long hash(const char* str) {
    unsigned long h = 5381;
    int c;
    while ((c = *str++))
        h = ((h << 5) + h) + c;
    return h;
}

void ht_init(HashTable* ht) {
    for (int i = 0; i < TABLE_SIZE; i++)
        ht->buckets[i] = NULL;
    ht->count = 0;
}

void ht_insert(HashTable* ht, const char* key, int value) {
    unsigned long idx = hash(key) % TABLE_SIZE;
    Entry* curr = ht->buckets[idx];
    while (curr) {
        if (strcmp(curr->key, key) == 0) {
            curr->value = value;
            return;
        }
        curr = curr->next;
    }
    Entry* n = malloc(sizeof(Entry));
    n->key = strdup(key);
    n->value = value;
    n->next = ht->buckets[idx];
    ht->buckets[idx] = n;
    ht->count++;
}

bool ht_get(HashTable* ht, const char* key, int* out) {
    unsigned long idx = hash(key) % TABLE_SIZE;
    Entry* curr = ht->buckets[idx];
    while (curr) {
        if (strcmp(curr->key, key) == 0) {
            *out = curr->value;
            return true;
        }
        curr = curr->next;
    }
    return false;
}

void ht_free(HashTable* ht) {
    for (int i = 0; i < TABLE_SIZE; i++) {
        Entry* curr = ht->buckets[i];
        while (curr) {
            Entry* temp = curr;
            curr = curr->next;
            free(temp->key);
            free(temp);
        }
    }
}

int main(void) {
    HashTable ht;
    ht_init(&ht);
    ht_insert(&ht, "apple", 100);
    ht_insert(&ht, "banana", 200);
    ht_insert(&ht, "cherry", 300);
    ht_insert(&ht, "date", 400);

    int val;
    if (ht_get(&ht, "banana", &val))
        printf("banana -> %d\n", val);
    if (ht_get(&ht, "cherry", &val))
        printf("cherry -> %d\n", val);
    if (!ht_get(&ht, "grape", &val))
        printf("grape not found\n");
    printf("Total entries: %d\n", ht.count);
    ht_free(&ht);
    return 0;
}

/* Open addressing with linear probing */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

#define TABLE_SIZE 16
#define EMPTY NULL
#define TOMBSTONE ((char*)-1)

typedef struct {
    char* key;
    int value;
} OAEntry;

typedef struct {
    OAEntry entries[TABLE_SIZE];
    int count;
} OAHashTable;

unsigned long hash(const char* s) {
    unsigned long h = 5381; int c;
    while ((c = *s++)) h = ((h << 5) + h) + c;
    return h;
}

void oa_init(OAHashTable* ht) {
    for (int i = 0; i < TABLE_SIZE; i++)
        ht->entries[i].key = EMPTY;
    ht->count = 0;
}

void oa_insert(OAHashTable* ht, const char* key, int value) {
    if (ht->count >= TABLE_SIZE * 0.75) {
        printf("Table full, needs resize\n"); return;
    }
    unsigned long idx = hash(key) % TABLE_SIZE;
    while (ht->entries[idx].key != EMPTY && ht->entries[idx].key != TOMBSTONE) {
        if (strcmp(ht->entries[idx].key, key) == 0) {
            ht->entries[idx].value = value; return;
        }
        idx = (idx + 1) % TABLE_SIZE;
    }
    ht->entries[idx].key = strdup(key);
    ht->entries[idx].value = value;
    ht->count++;
}

bool oa_get(OAHashTable* ht, const char* key, int* out) {
    unsigned long idx = hash(key) % TABLE_SIZE;
    int start = idx;
    while (ht->entries[idx].key != EMPTY) {
        if (ht->entries[idx].key != TOMBSTONE &&
            strcmp(ht->entries[idx].key, key) == 0) {
            *out = ht->entries[idx].value;
            return true;
        }
        idx = (idx + 1) % TABLE_SIZE;
        if (idx == start) break;
    }
    return false;
}

int main(void) {
    OAHashTable ht;
    oa_init(&ht);
    oa_insert(&ht, "red", 1);
    oa_insert(&ht, "green", 2);
    oa_insert(&ht, "blue", 3);
    int v;
    if (oa_get(&ht, "green", &v))
        printf("green -> %d\n", v);
    return 0;
}

#include <stdio.h>
#include <stdint.h>

void bit_demo(void) {
    uint8_t flags = 0b00001111;
    printf("Initial: 0x%02X\n", flags);

    flags |= (1 << 5);
    printf("Set bit 5: 0x%02X\n", flags);

    flags &= ~(1 << 1);
    printf("Clear bit 1: 0x%02X\n", flags);

    flags ^= (1 << 7);
    printf("Toggle bit 7: 0x%02X\n", flags);

    if (flags & (1 << 3))
        printf("Bit 3 is SET\n");

    int count = 0;
    uint8_t temp = flags;
    while (temp) {
        temp &= temp - 1;
        count++;
    }
    printf("Set bits: %d\n", count);

    int n = 16;
    if (n && !(n & (n - 1)))
        printf("%d is a power of two\n", n);

    int a = 5, b = 9;
    a ^= b; b ^= a; a ^= b;
    printf("Swapped: a=%d, b=%d\n", a, b);
}

