/* Permission flags like Unix file modes */
#include <stdio.h>

#define PERM_READ    0400
#define PERM_WRITE   0200
#define PERM_EXEC    0100
#define PERM_READGRP 0040
#define PERM_WRITEGRP 0020
#define PERM_EXECGRP 0010

void print_permissions(int mode) {
    printf("Permissions: %c%c%c%c%c%c\n",
        (mode & PERM_READ)  ? 'r' : '-',
        (mode & PERM_WRITE) ? 'w' : '-',
        (mode & PERM_EXEC)  ? 'x' : '-',
        (mode & PERM_READGRP)  ? 'r' : '-',
        (mode & PERM_WRITEGRP) ? 'w' : '-',
        (mode & PERM_EXECGRP)  ? 'x' : '-');
}

int main(void) {
    int mode = PERM_READ | PERM_WRITE | PERM_EXEC | PERM_READGRP | PERM_EXECGRP;
    print_permissions(mode);
    mode |= PERM_WRITEGRP;
    print_permissions(mode);
    mode &= ~PERM_EXEC;
    print_permissions(mode);
    return 0;
}

