/* Parsing CSV with strtok (not thread-safe) */
#include <stdio.h>
#include <string.h>
#include <stdlib.h>

void parse_csv(const char* line) {
    char* buffer = strdup(line);
    char* token = strtok(buffer, ",");
    int col = 0;
    while (token) {
        printf("Column %d: '%s'\n", col++, token);
        token = strtok(NULL, ",");
    }
    free(buffer);
}

/* Thread-safe with strtok_r */
void parse_csv_safe(const char* line) {
    char* buffer = strdup(line);
    char* saveptr;
    char* token = strtok_r(buffer, ",", &saveptr);
    int col = 0;
    while (token) {
        printf("Column %d: '%s'\n", col++, token);
        token = strtok_r(NULL, ",", &saveptr);
    }
    free(buffer);
}

typedef struct {
    char name[20];
    int score;
} Player;

int cmp_player(const void* a, const void* b) {
    const Player* pa = a;
    const Player* pb = b;
    return pb->score - pa->score;
}

int main(void) {
    parse_csv("Alice,95,A+");
    printf("\n");
    parse_csv_safe("Bob,87,B+");

    Player players[] = {{"Alice", 95}, {"Bob", 87}, {"Carol", 92}};
    qsort(players, 3, sizeof(Player), cmp_player);
    printf("\nRankings:\n");
    for (int i = 0; i < 3; i++)
        printf("%d. %s (%d)\n", i+1, players[i].name, players[i].score);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/wait.h>

int main(void) {
    pid_t pid = fork();
    if (pid < 0) {
        perror("fork failed");
        return 1;
    }
    if (pid == 0) {
        printf("[Child] PID=%d, Parent PID=%d\n", getpid(), getppid());
        execl("/bin/ls", "ls", "-l", NULL);
        perror("execl failed");
        exit(1);
    } else {
        printf("[Parent] Waiting for child PID=%d\n", pid);
        int status;
        pid_t child_pid = wait(&status);
        if (WIFEXITED(status)) {
            printf("[Parent] Child %d exited with code %d\n",
                   child_pid, WEXITSTATUS(status));
        }
    }
    return 0;
}

/* Pipe between parent and child: ls | wc -l */
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/wait.h>

int main(void) {
    int pipefd[2];
    if (pipe(pipefd) == -1) {
        perror("pipe"); return 1;
    }
    pid_t pid = fork();
    if (pid < 0) {
        perror("fork"); return 1;
    }
    if (pid == 0) {
        close(pipefd[0]);
        dup2(pipefd[1], STDOUT_FILENO);
        close(pipefd[1]);
        execlp("ls", "ls", "-l", NULL);
        perror("execlp");
        exit(1);
    } else {
        close(pipefd[1]);
        dup2(pipefd[0], STDIN_FILENO);
        close(pipefd[0]);
        execlp("wc", "wc", "-l", NULL);
        perror("execlp");
        return 1;
    }
}

#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define NUM_THREADS 4
#define INCREMENTS 100000

int counter = 0;
pthread_mutex_t mutex;

void* increment(void* arg) {
    (void)arg;
    for (int i = 0; i < INCREMENTS; i++) {
        pthread_mutex_lock(&mutex);
        counter++;
        pthread_mutex_unlock(&mutex);
    }
    return NULL;
}

int main(void) {
    pthread_t threads[NUM_THREADS];
    pthread_mutex_init(&mutex, NULL);

    for (int i = 0; i < NUM_THREADS; i++)
        pthread_create(&threads[i], NULL, increment, NULL);

    for (int i = 0; i < NUM_THREADS; i++)
        pthread_join(threads[i], NULL);

    printf("Expected: %d, Actual: %d\n",
           NUM_THREADS * INCREMENTS, counter);
    pthread_mutex_destroy(&mutex);
    return 0;
}

/* Producer-Consumer with condition variables */
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <unistd.h>

#define BUFFER_SIZE 10

int buffer[BUFFER_SIZE];
int count = 0;
int in = 0, out = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t not_full = PTHREAD_COND_INITIALIZER;
pthread_cond_t not_empty = PTHREAD_COND_INITIALIZER;

void* producer(void* arg) {
    (void)arg;
    for (int i = 1; i <= 20; i++) {
        pthread_mutex_lock(&mutex);
        while (count == BUFFER_SIZE)
            pthread_cond_wait(&not_full, &mutex);
        buffer[in] = i;
        in = (in + 1) % BUFFER_SIZE;
        count++;
        printf("Produced: %d\n", i);
        pthread_cond_signal(&not_empty);
        pthread_mutex_unlock(&mutex);
        usleep(100000);
    }
    return NULL;
}

void* consumer(void* arg) {
    (void)arg;
    for (int i = 1; i <= 20; i++) {
        pthread_mutex_lock(&mutex);
        while (count == 0)
            pthread_cond_wait(&not_empty, &mutex);
        int item = buffer[out];
        out = (out + 1) % BUFFER_SIZE;
        count--;
        printf("  Consumed: %d\n", item);
        pthread_cond_signal(&not_full);
        pthread_mutex_unlock(&mutex);
        usleep(150000);
    }
    return NULL;
}

int main(void) {
    pthread_t prod, cons;
    pthread_create(&prod, NULL, producer, NULL);
    pthread_create(&cons, NULL, consumer, NULL);
    pthread_join(prod, NULL);
    pthread_join(cons, NULL);
    return 0;
}

/* TCP Echo Server */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>

#define PORT 8080
#define BUFFER_SIZE 1024

int main(void) {
    int server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        perror("socket"); return 1;
    }

    int opt = 1;
    setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr*)&addr, sizeof(addr)) < 0) {
        perror("bind"); return 1;
    }

    if (listen(server_fd, 5) < 0) {
        perror("listen"); return 1;
    }

    printf("Server listening on port %d\n", PORT);

    struct sockaddr_in client_addr;
    socklen_t client_len = sizeof(client_addr);
    int client_fd = accept(server_fd,
                           (struct sockaddr*)&client_addr, &client_len);
    if (client_fd < 0) {
        perror("accept"); return 1;
    }

    printf("Client connected\n");
    char buffer[BUFFER_SIZE];
    int bytes = recv(client_fd, buffer, BUFFER_SIZE - 1, 0);
    if (bytes > 0) {
        buffer[bytes] = '\0';
        printf("Received: %s\n", buffer);
        send(client_fd, buffer, bytes, 0);  /* Echo back */
    }

    close(client_fd);
    close(server_fd);
    return 0;
}

/* TCP Echo Client */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>

#define PORT 8080
#define BUFFER_SIZE 1024

int main(void) {
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        perror("socket"); return 1;
    }

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(PORT);
    inet_pton(AF_INET, "127.0.0.1", &server_addr.sin_addr);

    if (connect(sock, (struct sockaddr*)&server_addr,
                sizeof(server_addr)) < 0) {
        perror("connect"); return 1;
    }

    const char* msg = "Hello, Server!";
    send(sock, msg, strlen(msg), 0);
    printf("Sent: %s\n", msg);

    char buffer[BUFFER_SIZE];
    int bytes = recv(sock, buffer, BUFFER_SIZE - 1, 0);
    if (bytes > 0) {
        buffer[bytes] = '\0';
        printf("Echo: %s\n", buffer);
    }

    close(sock);
    return 0;
}

/* Signal handling with sigaction */
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>

volatile sig_atomic_t keep_running = 1;

void handle_sigint(int sig) {
    (void)sig;
    const char msg[] = "\nCaught SIGINT, shutting down gracefully...\n";
    write(STDOUT_FILENO, msg, sizeof(msg) - 1);
    keep_running = 0;
}

void handle_sigalrm(int sig) {
    (void)sig;
    const char msg[] = "Timer tick!\n";
    write(STDOUT_FILENO, msg, sizeof(msg) - 1);
    alarm(2);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = handle_sigint;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    struct sigaction sa_alarm;
    sa_alarm.sa_handler = handle_sigalrm;
    sigemptyset(&sa_alarm.sa_mask);
    sa_alarm.sa_flags = 0;
    sigaction(SIGALRM, &sa_alarm, NULL);

    alarm(2);

    printf("Press Ctrl+C to exit. Waiting for alarms...\n");
    while (keep_running) {
        pause();
    }

    printf("Clean exit.\n");
    return 0;
}

/* Shared memory IPC between parent and child */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/ipc.h>
#include <sys/shm.h>

#define SHM_SIZE 1024

int main(void) {
    key_t key = ftok("shmfile", 65);
    int shmid = shmget(key, SHM_SIZE, IPC_CREAT | 0666);
    if (shmid < 0) { perror("shmget"); return 1; }

    char* str = (char*)shmat(shmid, NULL, 0);
    if (str == (char*)-1) { perror("shmat"); return 1; }

    pid_t pid = fork();
    if (pid < 0) { perror("fork"); return 1; }

    if (pid == 0) {
        sleep(1);
        printf("[Child] Read from shared memory: %s\n", str);
        shmdt(str);
    } else {
        strcpy(str, "Hello from parent via shared memory!");
        printf("[Parent] Wrote to shared memory\n");
        wait(NULL);
        shmdt(str);
        shmctl(shmid, IPC_RMID, NULL);
    }
    return 0;
}

/* Memory-mapped file: read and modify */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/mman.h>
#include <sys/stat.h>

int main(void) {
    const char* filename = "mmap_demo.txt";

    int fd = open(filename, O_RDWR | O_CREAT, 0666);
    const char* init = "Hello, Memory Mapping!";
    write(fd, init, strlen(init));
    ftruncate(fd, 4096);

    char* map = mmap(NULL, 4096, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (map == MAP_FAILED) { perror("mmap"); return 1; }
    close(fd);

    printf("Original: %s\n", map);

    map[7] = 'M'; map[8] = 'M'; map[9] = 'A'; map[10] = 'P';
    msync(map, 4096, MS_SYNC);

    printf("Modified: %s\n", map);
    munmap(map, 4096);

    fd = open(filename, O_RDONLY);
    char buf[256];
    read(fd, buf, sizeof(buf));
    printf("On disk:  %s\n", buf);
    close(fd);
    unlink(filename);
    return 0;
}

/* Anonymous mmap: large zero-initialized allocation */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/mman.h>
#include <sys/wait.h>

int main(void) {
    size_t size = 1024 * 1024;

    char* big = mmap(NULL, size, PROT_READ | PROT_WRITE,
                     MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (big == MAP_FAILED) { perror("mmap"); return 1; }

    printf("big[0] = %d, big[size-1] = %d\n", big[0], big[size - 1]);
    strcpy(big, "Stored in anonymous mmap");
    printf("%s\n", big);

    pid_t pid = fork();
    if (pid == 0) {
        printf("[Child] sees: %s\n", big);
        strcpy(big, "Modified by child");
        exit(0);
    }
    wait(NULL);
    printf("[Parent] sees: %s\n", big);

    munmap(big, size);
    return 0;
}

/* C11 _Generic: type-generic max macro */
#include <stdio.h>

#define max(a, b) _Generic((a) + (b),\n    int: max_int,\n    double: max_double,\n    long: max_long\n)(a, b)

int max_int(int a, int b) { return a > b ? a : b; }
double max_double(double a, double b) { return a > b ? a : b; }
long max_long(long a, long b) { return a > b ? a : b; }

int main(void) {
    printf("max(3, 5) = %d\n", max(3, 5));
    printf("max(3.14, 2.71) = %f\n", max(3.14, 2.71));
    printf("max(100L, 50L) = %ld\n", max(100L, 50L));
    return 0;
}

