/* Secure input handling patterns */
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <errno.h>
#include <limits.h>

#define MAX_INPUT 256

void safe_copy(char* dest, size_t dest_size, const char* src) {
    if (dest_size == 0) return;
    size_t i;
    for (i = 0; i < dest_size - 1 && src[i] != '\0'; i++) {
        dest[i] = src[i];
    }
    dest[i] = '\0';
}

int safe_gets(char* buf, size_t size) {
    if (!fgets(buf, (int)size, stdin)) return -1;
    size_t len = strlen(buf);
    if (len > 0 && buf[len - 1] == '\n') {
        buf[len - 1] = '\0';
    }
    return 0;
}

int safe_atoi(const char* str, int* out) {
    char* endptr;
    errno = 0;
    long val = strtol(str, &endptr, 10);
    if (endptr == str || *endptr != '\0') return -1;
    if (errno == ERANGE || val < INT_MIN || val > INT_MAX) return -1;
    *out = (int)val;
    return 0;
}

int main(void) {
    char input[MAX_INPUT];
    printf("Enter a number: ");
    if (safe_gets(input, sizeof(input)) != 0) {
        fprintf(stderr, "Input error\n");
        return 1;
    }

    int num;
    if (safe_atoi(input, &num) != 0) {
        fprintf(stderr, "Invalid number: '%s'\n", input);
        return 1;
    }
    printf("Valid integer: %d\n", num);
    return 0;
}

