/* Minimal shell with fork/exec and built-ins */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/wait.h>

#define MAX_CMD 1024
#define MAX_ARGS 64

int builtin_cd(char** args) {
    if (args[1] == NULL) {
        fprintf(stderr, "cd: missing argument\n");
    } else if (chdir(args[1]) != 0) {
        perror("cd");
    }
    return 1;
}

int builtin_exit(char** args) {
    (void)args;
    exit(0);
}

int execute(char** args) {
    pid_t pid = fork();
    if (pid < 0) { perror("fork"); return 1; }
    if (pid == 0) {
        execvp(args[0], args);
        perror("execvp");
        exit(1);
    } else {
        int status;
        waitpid(pid, &status, 0);
    }
    return 1;
}

int parse_and_run(char* line) {
    char* args[MAX_ARGS];
    int i = 0;
    args[i] = strtok(line, " \t\n");
    while (args[i] != NULL && i < MAX_ARGS - 1) {
        args[++i] = strtok(NULL, " \t\n");
    }
    if (args[0] == NULL) return 1;

    if (strcmp(args[0], "cd") == 0) return builtin_cd(args);
    if (strcmp(args[0], "exit") == 0) return builtin_exit(args);
    return execute(args);
}

int main(void) {
    char line[MAX_CMD];
    while (1) {
        printf("myshell> ");
        fflush(stdout);
        if (fgets(line, sizeof(line), stdin) == NULL) break;
        parse_and_run(line);
    }
    return 0;
}

/* Shell with I/O redirection support */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/wait.h>

#define MAX_CMD 1024

int run_with_redirect(char** args, char* infile, char* outfile) {
    pid_t pid = fork();
    if (pid < 0) { perror("fork"); return 1; }
    if (pid == 0) {
        if (infile) {
            int fd = open(infile, O_RDONLY);
            if (fd < 0) { perror("open"); exit(1); }
            dup2(fd, STDIN_FILENO);
            close(fd);
        }
        if (outfile) {
            int fd = open(outfile, O_WRONLY | O_CREAT | O_TRUNC, 0644);
            if (fd < 0) { perror("open"); exit(1); }
            dup2(fd, STDOUT_FILENO);
            close(fd);
        }
        execvp(args[0], args);
        perror("execvp");
        exit(1);
    }
    wait(NULL);
    return 1;
}

