/* Simulated bare-metal GPIO control */
#include <stdio.h>
#include <stdint.h>
#include <stdbool.h>

static uint32_t gpioa_moder = 0;
static uint32_t gpioa_odr = 0;

#define GPIOA_MODER (*(volatile uint32_t*)&gpioa_moder)
#define GPIOA_ODR   (*(volatile uint32_t*)&gpioa_odr)

#define PIN5 5

void gpio_init_output(int pin) {
    GPIOA_MODER &= ~(0b11 << (pin * 2));
    GPIOA_MODER |=  (0b01 << (pin * 2));
}

void gpio_set(int pin, bool high) {
    if (high) GPIOA_ODR |=  (1 << pin);
    else      GPIOA_ODR &= ~(1 << pin);
}

bool gpio_read(int pin) {
    return (GPIOA_ODR >> pin) & 1;
}

void delay_ms(int ms) {
    printf("[Delay %d ms]\n", ms);
}

int main(void) {
    gpio_init_output(PIN5);
    int cycles = 0;
    while (1) {
        gpio_set(PIN5, true);
        printf("LED ON  (ODR=0x%08X)\n", GPIOA_ODR);
        delay_ms(500);
        gpio_set(PIN5, false);
        printf("LED OFF (ODR=0x%08X)\n", GPIOA_ODR);
        delay_ms(500);
        if (++cycles >= 3) break;
    }
    return 0;
}

