/* Graph with adjacency list and Dijkstra's algorithm */
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <limits.h>

#define MAX_VERTICES 100
#define INF INT_MAX

typedef struct Edge {
    int dest;
    int weight;
    struct Edge* next;
} Edge;

typedef struct {
    Edge* head;
} Vertex;

typedef struct {
    Vertex vertices[MAX_VERTICES];
    int num_vertices;
} Graph;

void graph_init(Graph* g, int n) {
    g->num_vertices = n;
    for (int i = 0; i < n; i++) g->vertices[i].head = NULL;
}

void add_edge(Graph* g, int src, int dest, int weight) {
    Edge* e = malloc(sizeof(Edge));
    e->dest = dest; e->weight = weight;
    e->next = g->vertices[src].head;
    g->vertices[src].head = e;
}

typedef struct { int vertex; int dist; } HeapNode;
typedef struct {
    HeapNode data[MAX_VERTICES];
    int size;
} MinHeap;

void heap_swap(HeapNode* a, HeapNode* b) { HeapNode t = *a; *a = *b; *b = t; }

void heap_push(MinHeap* h, int v, int d) {
    int i = h->size++;
    h->data[i] = (HeapNode){v, d};
    while (i > 0) {
        int p = (i - 1) / 2;
        if (h->data[p].dist <= h->data[i].dist) break;
        heap_swap(&h->data[p], &h->data[i]);
        i = p;
    }
}

HeapNode heap_pop(MinHeap* h) {
    HeapNode root = h->data[0];
    h->data[0] = h->data[--h->size];
    int i = 0;
    while (1) {
        int l = 2*i + 1, r = 2*i + 2, smallest = i;
        if (l < h->size && h->data[l].dist < h->data[smallest].dist) smallest = l;
        if (r < h->size && h->data[r].dist < h->data[smallest].dist) smallest = r;
        if (smallest == i) break;
        heap_swap(&h->data[i], &h->data[smallest]);
        i = smallest;
    }
    return root;
}

void dijkstra(Graph* g, int src, int dist[]) {
    bool visited[MAX_VERTICES] = {false};
    MinHeap heap = {.size = 0};
    for (int i = 0; i < g->num_vertices; i++) dist[i] = INF;
    dist[src] = 0;
    heap_push(&heap, src, 0);

    while (heap.size > 0) {
        HeapNode node = heap_pop(&heap);
        int u = node.vertex;
        if (visited[u]) continue;
        visited[u] = true;

        for (Edge* e = g->vertices[u].head; e; e = e->next) {
            int v = e->dest, w = e->weight;
            if (!visited[v] && dist[u] != INF && dist[u] + w < dist[v]) {
                dist[v] = dist[u] + w;
                heap_push(&heap, v, dist[v]);
            }
        }
    }
}

int main(void) {
    Graph g;
    graph_init(&g, 6);
    add_edge(&g, 0, 1, 4); add_edge(&g, 0, 2, 2);
    add_edge(&g, 1, 2, 1); add_edge(&g, 1, 3, 5);
    add_edge(&g, 2, 3, 8); add_edge(&g, 2, 4, 10);
    add_edge(&g, 3, 4, 2); add_edge(&g, 3, 5, 6);
    add_edge(&g, 4, 5, 3);

    int dist[6];
    dijkstra(&g, 0, dist);
    printf("Shortest distances from vertex 0:\n");
    for (int i = 0; i < 6; i++)
        printf("  to %d: %d\n", i, dist[i]);
    return 0;
}

/* Min-Heap (Priority Queue) implementation */
#include <stdio.h>
#include <stdlib.h>

#define HEAP_CAP 100

typedef struct { int key; int priority; } PQItem;

typedef struct {
    PQItem items[HEAP_CAP];
    int size;
} MinPQ;

void pq_init(MinPQ* pq) { pq->size = 0; }

void pq_insert(MinPQ* pq, int key, int pri) {
    int i = pq->size++;
    pq->items[i] = (PQItem){key, pri};
    while (i > 0) {
        int p = (i - 1) / 2;
        if (pq->items[p].priority <= pq->items[i].priority) break;
        PQItem t = pq->items[p]; pq->items[p] = pq->items[i]; pq->items[i] = t;
        i = p;
    }
}

PQItem pq_extract_min(MinPQ* pq) {
    PQItem root = pq->items[0];
    pq->items[0] = pq->items[--pq->size];
    int i = 0;
    while (1) {
        int l = 2*i+1, r = 2*i+2, min = i;
        if (l < pq->size && pq->items[l].priority < pq->items[min].priority) min = l;
        if (r < pq->size && pq->items[r].priority < pq->items[min].priority) min = r;
        if (min == i) break;
        PQItem t = pq->items[i]; pq->items[i] = pq->items[min]; pq->items[min] = t;
        i = min;
    }
    return root;
}

int main(void) {
    MinPQ pq;
    pq_init(&pq);
    pq_insert(&pq, 'A', 5);
    pq_insert(&pq, 'B', 3);
    pq_insert(&pq, 'C', 7);
    pq_insert(&pq, 'D', 1);
    pq_insert(&pq, 'E', 4);

    printf("Extracted in priority order: ");
    while (pq.size > 0) {
        PQItem item = pq_extract_min(&pq);
        printf("%c(%d) ", item.key, item.priority);
    }
    printf("\n");
    return 0;
}

/* Basic regex matching */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <regex.h>

int main(void) {
    const char* pattern = "[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}";
    const char* text = "Contact us at support@example.com or sales@company.org";

    regex_t regex;
    int ret = regcomp(&regex, pattern, REG_EXTENDED);
    if (ret != 0) {
        char errbuf[256];
        regerror(ret, &regex, errbuf, sizeof(errbuf));
        fprintf(stderr, "Regex compile error: %s\n", errbuf);
        return 1;
    }

    regmatch_t match;
    const char* p = text;
    printf("Found emails:\n");
    while (regexec(&regex, p, 1, &match, 0) == 0) {
        if (match.rm_so == -1) break;
        printf("  %.*s\n", (int)(match.rm_eo - match.rm_so), p + match.rm_so);
        p += match.rm_eo;
    }

    regfree(&regex);
    return 0;
}

/* Regex with capture groups */
#include <stdio.h>
#include <string.h>
#include <regex.h>

int main(void) {
    const char* pattern = "([0-9]{4})-([0-9]{2})-([0-9]{2})";
    const char* text = "Event on 2026-07-31 and deadline 2026-08-15";

    regex_t regex;
    regcomp(&regex, pattern, REG_EXTENDED);

    regmatch_t matches[4];
    const char* p = text;

    printf("Parsed dates:\n");
    while (regexec(&regex, p, 4, matches, 0) == 0) {
        printf("  Full: %.*s\n",
               (int)(matches[0].rm_eo - matches[0].rm_so), p + matches[0].rm_so);
        printf("    Year:  %.*s\n",
               (int)(matches[1].rm_eo - matches[1].rm_so), p + matches[1].rm_so);
        printf("    Month: %.*s\n",
               (int)(matches[2].rm_eo - matches[2].rm_so), p + matches[2].rm_so);
        printf("    Day:   %.*s\n\n",
               (int)(matches[3].rm_eo - matches[3].rm_so), p + matches[3].rm_so);
        p += matches[0].rm_eo;
    }

    regfree(&regex);
    return 0;
}

