/* math_plugin.c - compiled to math_plugin.so */
#include "plugin.h"

static int add(int a, int b) { return a + b; }

static PluginInfo info = {"Math Plugin", "1.0", add};

PluginInfo* plugin_init(void) { return &info; }

/* Plugin loader (main program) */
#include <stdio.h>
#include <stdlib.h>
#include <dlfcn.h>
#include "plugin.h"

int main(void) {
    const char* plugin_path = "./math_plugin.so";

    void* handle = dlopen(plugin_path, RTLD_LAZY);
    if (!handle) {
        fprintf(stderr, "dlopen error: %s\n", dlerror());
        return 1;
    }

    plugin_init_func init = (plugin_init_func)dlsym(handle, "plugin_init");
    char* error = dlerror();
    if (error != NULL) {
        fprintf(stderr, "dlsym error: %s\n", error);
        dlclose(handle);
        return 1;
    }

    PluginInfo* info = init();
    printf("Loaded plugin: %s v%s\n", info->name, info->version);
    printf("plugin_execute(10, 20) = %d\n", info->execute(10, 20));

    dlclose(handle);
    return 0;
}
